  overview:'アッバース朝の中央権力が弱まると、各地で自立した王朝やカリフ政権が生まれ、イスラーム世界は政治的に分裂していきました。イベリア半島の後ウマイヤ朝、北アフリカ・エジプトのファーティマ朝、イラン系のブワイフ朝やトルコ系のセルジューク朝などが並び立ちます。一方、イスラームの信仰やアラビア語を基盤とする文化・交易のつながりは広域に保たれました。',
