  overview:'後漢末の混乱から魏・呉・蜀の三国時代となり、西晋が一時中国を統一しました。しかし皇族間の八王の乱などで国力が弱まり、北方では五胡が諸国を建てて五胡十六国時代となります。北魏が華北を統一する一方、南には東晋や宋・斉・梁・陳が交替して南北朝時代が続き、隋が589年に南北を統一しました。',
