   {heading:'① 三国時代と西晋の統一',body:'後漢末の混乱の後、華北の魏、長江流域の呉、四川盆地の蜀が並び立ちました。魏の実権を握った司馬氏は、265年に西晋を建てます。西晋は280年に呉を滅ぼして中国を統一しましたが、皇族間の争いである八王の乱によって国力が衰え、各地の反乱や北方民族の進出を招きました。',highlights:['三国＝魏・呉・蜀','西晋を建てた司馬氏','280年に西晋が中国を統一','八王の乱で西晋が弱体化']},
   {heading:'② 五胡十六国時代',body:'西晋が滅亡すると、北方では匈奴・鮮卑・羯・氐・羌などの諸集団が相次いで国を建て、華北は分裂しました。この時期を五胡十六国時代と呼びます。西晋の皇族は江南に移って東晋を建て、漢人の政権が南方に存続しました。北方の動乱を背景に、多くの人々が華北から江南へ移住しました。',highlights:['五胡＝匈奴・鮮卑・羯・氐・羌','北方で諸国が興亡した時代＝五胡十六国','江南では東晋が成立']},
   {heading:'③ 北魏と孝文帝の改革',body:'鮮卑の拓跋氏が建てた北魏は、439年に華北を統一しました。孝文帝は漢人社会との融和を目指して都を平城から洛陽へ移し、漢語の使用や漢風の姓への改姓などの漢化政策を進めます。こうした改革は北方民族と漢人の文化的な融合を促しました。',highlights:['北魏＝鮮卑の拓跋氏が建国','439年に華北を統一','孝文帝＝洛陽遷都・漢化政策']},
   {heading:'④ 南北朝時代と隋の統一',body:'北魏が分裂した後、華北では東魏・西魏、さらに北斉・北周などが交替しました。江南では東晋の後に宋・斉・梁・陳が続き、南朝と呼ばれます。華北の北朝と江南の南朝が対立したこの時代が南北朝時代です。北周の外戚であった楊堅は581年に隋を建て、589年に南朝の陳を滅ぼして中国を再統一しました。',highlights:['南朝＝宋・斉・梁・陳','北朝＝北魏の分裂後、北斉・北周などが興亡','隋の楊堅が589年に中国を統一']}
