  overview:'南北朝の分裂を終わらせた隋は、科挙や大運河などを整えましたが、高句麗遠征の失敗や重い負担への反発から短命に終わりました。唐は律令体制のもとで繁栄し、均田制・租庸調制・府兵制を運用します。安史の乱以後は節度使が自立し、両税法への転換を経て、黄巣の乱の後に滅亡しました。',
