  overview:'4世紀後半、フン人の西進をきっかけにゲルマン諸部族が大移動を始め、西ローマ帝国内へ移住して王国を築きました。西ゴート・ヴァンダル・東ゴート・フランクなどの諸王国が成立し、476年に西ローマ帝国が滅亡した後のヨーロッパの基盤となります。フランク王国はカトリック教会と結びついて勢力を伸ばしました。',
