   {heading:'④ 清の考証学・文学と西洋知識',body:'清代には古典文献を実証的に調べる考証学が盛んになりました。康熙帝の時代に『康熙字典』、乾隆帝の時代に『四庫全書』が編纂されます。文学では曹雪芹の『紅楼夢』や蒲松齢の『聊斎志異』が知られます。イエズス会宣教師は天文学・数学・地理などの知識を伝えましたが、中国の祖先祭祀や孔子祭祀をめぐる典礼問題が起き、清朝は18世紀に布教を制限しました。',highlights:['考証学＝文献・古典を実証的に研究','『康熙字典』・『四庫全書』','『紅楼夢』＝曹雪芹、『聊斎志異』＝蒲松齢','イエズス会の活動と典礼問題']}
