   {heading:'② 叙任権闘争と皇帝権の弱体化',body:'皇帝と教皇は、聖職者を任命する権利（叙任権）をめぐって対立しました。皇帝ハインリヒ4世は1077年にカノッサで教皇グレゴリウス7世に謝罪し、1122年のヴォルムス協約で争いに一定の決着がつきます。13世紀の大空位時代を経て諸侯の影響力が強まり、1356年の金印勅書は選帝侯による皇帝選出を定めました。',highlights:['叙任権闘争＝聖職者任命をめぐる皇帝と教皇の争い','1077年＝カノッサの屈辱','1356年＝金印勅書が選帝侯を定める']},
   {heading:'③ イベリア半島とレコンキスタ',body:'711年、イスラーム勢力がイベリア半島へ進出し、西ゴート王国を滅ぼしました。北部に残ったキリスト教勢力は諸王国を築き、南へ勢力を広げる国土回復運動（レコンキスタ）を長期にわたり進めます。ポルトガルは12世紀に独立し、カスティリャとアラゴンは婚姻を通じて結びつきました。1492年、両王国の連合がグラナダを攻略し、レコンキスタは完了します。',highlights:['711年＝イスラーム勢力が半島へ進出','レコンキスタ＝キリスト教勢力による国土回復運動','1492年＝グラナダ陥落、国土回復運動の完了']}
