   {heading:'② キリスト教と文字',body:'9世紀にビザンツ帝国の宣教師キリルとメトディオスがスラブ人への宣教を進めました。彼らの活動はスラブ語による典礼・文書文化の発展に影響し、キリル文字の成立にもつながりました。東・南スラブの多くは正教会の影響を受け、西スラブのポーランドやチェコではローマ＝カトリックが広まりました。',highlights:['キリル・メトディオス＝スラブ人への宣教','東・南スラブの多く＝正教会','西スラブのポーランド・チェコ＝カトリック']},
   {heading:'③ 東スラブとキエフ公国',body:'東スラブ地域ではキエフを中心とする公国が成立し、ビザンツ帝国との交易・文化交流を深めました。988年、キエフ大公ウラディーミル1世が正教を受け入れたことで、東スラブ世界にビザンツ系の宗教・文化が定着します。13世紀のモンゴル勢力の侵入はキエフ公国を衰退させ、後のモスクワ大公国の台頭につながりました。',highlights:['キエフ公国＝東スラブの初期国家','988年＝ウラディーミル1世が正教を受容','モンゴル侵入後にモスクワが台頭']},
   {heading:'④ 西・南スラブの国家',body:'西スラブではポーランド王国やボヘミア（チェコ）などが発展し、ラテン文字とカトリック文化の影響を受けました。南スラブ地域ではブルガリア帝国やセルビア王国が勢力を伸ばし、正教会やキリル文字文化が広がります。バルカン半島はビザンツ帝国や後のオスマン帝国の影響も強く受けました。',highlights:['ポーランド・ボヘミア＝西スラブの国家','ブルガリア・セルビア＝南スラブの国家','バルカン地域では帝国間の影響が交錯']}
