  overviewPoints:['北ヨーロッパ：ハンザ同盟とバルト海・北海交易','南ヨーロッパ：ヴェネツィア・ジェノヴァなどの地中海交易','シャンパーニュ大市や定期市が遠隔地商業・金融をつなぐ'],
