  overview:'ノルマン人は北欧系の人々で、ヴァイキングとして西ヨーロッパ各地へ移動・交易・征服を行いました。10世紀初めにロロがフランス王からノルマンディーを認められ、現地のキリスト教文化と融合します。11世紀にはノルマンディー公ウィリアムがイングランドを征服し、別のノルマン人勢力は南イタリア・シチリアを支配しました。',
  overviewPoints:['ノルマン人＝北欧系ヴァイキングの一派','ロロがノルマンディーを領有し、西フランク文化と融合','イングランド征服・南イタリアとシチリアの王国建設'],
