  sections:[
   {heading:'① ヴァイキングとノルマンディー',body:'ノルマン人は北欧系のヴァイキングで、船を用いて西ヨーロッパ沿岸を襲撃する一方、交易や移住も行いました。911年、フランス王はロロにセーヌ川下流域の支配を認め、ノルマンディー公領が成立します。ノルマン人はキリスト教に改宗し、フランス語や封建的な統治を取り入れて、周囲の社会と融合しました。',highlights:['ロロ＝ノルマンディーの支配者','911年＝サン＝クレール＝シュル＝エプト条約','北欧系から西フランク社会へ融合']},
   {heading:'② イングランド征服',body:'ノルマンディー公ウィリアムは、イングランド王位継承をめぐって1066年に海峡を渡り、ヘースティングズの戦いでハロルド2世を破りました。ウィリアム1世となった彼は土地を配分して王権を強化し、全国的な土地・財産調査の結果を1086年にドゥームズデイ＝ブックとしてまとめます。',highlights:['1066年＝ヘースティングズの戦い','ウィリアム1世＝ノルマン朝','1086年＝ドゥームズデイ＝ブック']},
   {heading:'③ 南イタリアとシチリア',body:'11世紀にはノルマン人が南イタリアへ進出し、ビザンツ帝国やイスラーム勢力の支配地を征服しました。ロベール＝ギスカールらが勢力を伸ばし、ルッジェーロ2世は1130年にシチリア王となります。シチリア王国ではラテン系・ギリシア系・アラブ系の住民や文化が共存し、地中海世界の交流拠点となりました。',highlights:['南イタリア・シチリアにノルマン人が進出','1130年＝ルッジェーロ2世がシチリア王に','多様な文化・宗教が交わる王国']},
   {heading:'④ ノルマン人の歴史的意義',body:'ノルマン人は征服者としてだけでなく、各地の制度や文化を取り入れた支配者として歴史に影響しました。イングランドではノルマン朝が王権と封建的土地支配を再編し、シチリアでは複数の文化圏を結ぶ宮廷文化が育ちます。北欧から地中海まで広がる移動は、中世ヨーロッパの政治地図と交易を変化させました。',highlights:['征服地の制度・言語・宗教を取り入れる','イングランド王権とシチリア王国の形成に影響','北欧から地中海までの広い移動']}
  ],
